files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  block-size: 100%;
}

.page {
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #f5f5f5;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
  block-size: 100%;
}

.menu {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: rgb(0 0 0 / 0.8);
}

.menu__close {
  position: absolute;
  z-index: 1;
  border: none;
  color: #fff;
  background-color: transparent;
  transition: opacity 0.3s ease-in-out;
  cursor: pointer;
  appearance: none;
  inline-size: 40px;
  aspect-ratio: 1/1;
  inset-block-start: 20px;
  inset-inline-end: 20px;
}

.menu__close:hover {
  opacity: 0.6;
}

.menu__close svg {
  inline-size: 100%;
}

.menu__list {
  display: grid;
  place-items: center;
  gap: 20px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.menu__item {
  transition: transform 10s ease;
}

.menu__item:hover {
  transform: perspective(500px) rotateX(360deg);
}

.menu__link {
  color: #fff;
  font-size: 2em;
  text-decoration: none;
  text-transform: uppercase;
}
